285	// Returns true (into `result`) if a node placed on `device` must be compiled.
286	absl::Status DeviceRequiresCompilation(
287	    const jit::DeviceInfoCache& device_info_cache, jit::DeviceId device,
288	    bool* result) {
289	  const XlaOpRegistry::DeviceRegistration* registration =
290	      device_info_cache.GetCompilationDevice(device);
291	  *result = registration->autoclustering_policy ==
292	            XlaOpRegistry::AutoclusteringPolicy::kAlways;
293	  return absl::OkStatus();
294	}
295	
296	// Replaces `n` with a `PartitionedCall` op that calls the same function.
297	absl::StatusOr<Node*> ReplaceFunctionCallWithPartitionedCall(
298	    const GraphOptimizationPassOptions& options,
299	    const FunctionLibraryDefinition& flib_def, Node* n, Graph* g,
300	    const NameAttrList& func, const Scope& root) {
301	  std::string config_string =
302	      options.session_options->config.SerializeAsString();
303	
304	  int input_count = absl::c_count_if(
305	      n->in_edges(), [](const Edge* e) { return !e->IsControlEdge(); });
306	
307	  std::vector<Output> args(input_count);
308	  for (const Edge* e : n->in_edges()) {
309	    if (!e->IsControlEdge()) {
310	      args[e->dst_input()] = Output(e->src(), e->src_output());
311	    }
312	  }
313	
314	  // In theory we can use PartitionedCall if the XLA cluster does not have any
315	  // stateful operations.  However, for now we choose to be conservative since
316	  // we don't have any evidence that choosing a stateless partitioned call helps
317	  // for performance.
318	  ops::StatefulPartitionedCall call(
319	      root.WithOpName("stateful_partitioned_call"), args, n->output_types(),
320	      func, ops::StatefulPartitionedCall::Attrs{}.ConfigProto(config_string));
321	
322	  for (const Edge* e : n->in_edges()) {
323	    if (e->IsControlEdge()) {
324	      g->AddControlEdge(e->src(), call.operation.node());
325	    }
326	  }
327	
328	  std::vector<const Edge*> edges_to_delete;
329	
330	  for (const Edge* e : n->out_edges()) {
331	    edges_to_delete.push_back(e);
332	    if (e->IsControlEdge()) {
333	      g->AddControlEdge(call.operation.node(), e->dst());
334	    } else {
335	      g->AddEdge(call.operation.node(), e->src_output(), e->dst(),
336	                 e->dst_input());
337	    }
338	  }
339	
340	  for (const Edge* e : edges_to_delete) {
341	    g->RemoveEdge(e);
342	  }
343	
344	  g->RemoveNode(n);
345	  return call.operation.node();
346	}
347	
348	absl::StatusOr<jit::DeviceId> InferDeviceForCluster(
349	    jit::DeviceInfoCache* device_info_cache, Node* n,
350	    const std::string& function_name,
351	    const FunctionLibraryDefinition& flib_def) {
352	  const FunctionDef* func_def = flib_def.Find(function_name);
353	  TF_RET_CHECK(func_def) << "Could not find " << function_name;
354	
355	  jit::DeviceSet device_set;
356	
357	  for (const NodeDef& ndef : func_def->node_def()) {
358	    VLOG(3) << ndef.DebugString();
359	    if (!ndef.device().empty()) {
360	      TF_ASSIGN_OR_RETURN(jit::DeviceId device_id,
361	                          device_info_cache->GetIdFor(ndef.device()));
362	      device_set.Insert(device_id);
363	    }
364	  }
365	
366	  if (!n->assigned_device_name().empty()) {
367	    // TODO(sanjoy): We need this because EncapsulateSubgraphsPass drops device
368	    // assignment when constant folding.  We should fix EncapsulateSubgraphsPass
369	    // instead.
370	    TF_ASSIGN_OR_RETURN(jit::DeviceId device_id,
371	                        device_info_cache->GetIdFor(n->assigned_device_name()));
372	    device_set.Insert(device_id);
373	  }
374	
375	  TF_ASSIGN_OR_RETURN(jit::DeviceId result,
376	                      PickDeviceForXla(*device_info_cache, device_set,
377	                                       /*allow_mixing_unknown_and_cpu=*/true));
378	  VLOG(2) << "For " << function_name << " PickDeviceForXla("
379	          << device_info_cache->DebugString(device_set) << ") -> "
380	          << device_info_cache->GetNameFor(result);
381	  return result;
382	}
383	
384	std::vector<Output> GetXlaRunArgs(const Scope& s,
385	                                  const XlaClusterInfo& cluster_info,
386	                                  const DebuggingOpts& debugging_opts) {
387	  std::vector<Output> xla_run_args;
388	  xla_run_args.reserve(cluster_info.non_constant_inputs.size() +
389	                       cluster_info.resource_inputs.size());
390	  int input_idx = 0;
391	  for (const Output& o : cluster_info.non_constant_inputs) {
392	    if (debugging_opts.check_input_numerics && DataTypeIsFloating(o.type())) {
393	      ops::CheckNumerics check_numerics_op(
394	          s.WithOpName("check_input_", input_idx), o,
395	          absl::StrCat("CheckNumerics failed for input ", input_idx, "(",
396	                       o.name(), ") into ", cluster_info.function.name()));
397	      xla_run_args.push_back(check_numerics_op);
398	    } else {
399	      xla_run_args.push_back(o);
400	    }
401	    input_idx++;
402	  }
403	  absl::c_copy(cluster_info.resource_inputs, std::back_inserter(xla_run_args));
404	  return xla_run_args;
405	}
406	
407	absl::StatusOr<MemoryTypeVector> GetOutputMemoryTypes(const Scope& root,
408	                                                      Node* n) {
409	  MemoryTypeVector input_mtypes, output_mtypes;
410	  DeviceType device_type("");
411	  TF_RETURN_IF_ERROR(
412	      DeviceNameToDeviceType(n->assigned_device_name(), &device_type));
413	  TF_RETURN_IF_ERROR(MemoryTypesForNode(root.graph()->op_registry(),
414	                                        device_type, n->def(), &input_mtypes,
415	                                        &output_mtypes));
416	  return output_mtypes;
417	}
418	
419	// Predicate INT32 typed inputs to `n` on the deadness of
420	// `predicate_as_control`.
421	//
422	// This is a performance optimization.  Since INT32 arguments to a
423	// PartitionedCall are placed on the host, a producer that produces them on the
424	// device will incur a D2H copy, even if the PartitionedCall is not executed
425	// (i.e. even if we choose to execute the XLA compiled computation via _XlaRun).
426	// To prevent this, we add control dependencies to make the int32 input edges
427	// into the PartitionedCall dead.  With this change the D2H copy only happens if
428	// the PartitionedCall is actually executed.
429	absl::Status PredicateInt32Inputs(const Scope& root, Node* n,
430	                                  Operation predicate_as_control) {
431	  std::vector<Output> int32_inputs;
432	  std::vector<int> int32_inputs_input_idxs;
433	  for (const Edge* e : n->in_edges()) {
434	    if (e->IsControlEdge()) {
435	      continue;
436	    }
437	
438	    if (e->src()->output_type(e->src_output()) == DT_INT32) {
439	      TF_ASSIGN_OR_RETURN(MemoryTypeVector source_output_mem_types,
440	                          GetOutputMemoryTypes(root, e->src()));
441	      if (source_output_mem_types[e->src_output()] == DEVICE_MEMORY) {
442	        int32_inputs.push_back(Output(e->src(), e->src_output()));
443	        int32_inputs_input_idxs.push_back(e->dst_input());
444	      }
445	    }
446	  }
447	
448	  if (int32_inputs.empty()) {
449	    return absl::OkStatus();
450	  }
451	
452	  // Create a single IdentityN that is dead if and only if
453	  // `predicate_as_control` is dead.
454	  //
455	  // IdentityN is also special in that, unlike `Identity`, it does not place
456	  // int32 inputs in host memory.  Placing int32 inputs in host memory would
457	  // defeat the purpose of adding this indirection.
458	  ops::IdentityN identity_n(root.WithOpName("int32_id_n"), int32_inputs);
459	  root.graph()->AddControlEdge(predicate_as_control.node(),
460	                               identity_n.operation.node());
461	
462	  for (int i = 0, end = int32_inputs.size(); i < end; i++) {
463	    TF_RETURN_IF_ERROR(root.graph()->UpdateEdge(identity_n[i].node(), i, n,
464	                                                int32_inputs_input_idxs[i]));
465	  }
466	
467	  return absl::OkStatus();
468	}
469	
470	absl::Status ReplaceNodeWithXlaCompileAndXlaRun(
471	    jit::DeviceInfoCache* device_info_cache,
472	    const GraphOptimizationPassOptions& options,
473	    const FunctionLibraryDefinition& flib_def, bool lazy_compilation_enabled,
474	    const DebuggingOpts& debugging_opts, Graph* g, Node* n) {
475	  XlaClusterInfo cluster_info;
476	  TF_RETURN_IF_ERROR(GetXlaClusterInfo(n, &cluster_info));
477	
478	  TF_ASSIGN_OR_RETURN(
479	      jit::DeviceId device,
480	      InferDeviceForCluster(device_info_cache, n, cluster_info.function.name(),
481	                            flib_def));
482	
483	  bool requires_compilation;
484	  TF_RETURN_IF_ERROR(DeviceRequiresCompilation(*device_info_cache, device,
485	                                               &requires_compilation));
486	  if (!lazy_compilation_enabled) {
487	    requires_compilation = true;
488	  }
489	
490	  std::string device_name_str =
491	      std::string(device_info_cache->GetNameFor(device));
492	
493	  absl::Status status;
494	  Scope root = NewInternalScope(g, &status, /*refiner=*/nullptr)
495	                   .NewSubScope(n->name())
496	                   .WithDevice(n->requested_device())
497	                   .WithAssignedDevice(device_name_str);
498	
499	  ops::_XlaCompile xla_compile(root.WithOpName("xla_compile"),
500	                               /*constants=*/cluster_info.constant_inputs,
501	                               /*args=*/cluster_info.non_constant_inputs,
502	                               /*resources=*/cluster_info.resource_inputs,
503	                               /*must_compile=*/requires_compilation,
504	                               cluster_info.function);
505	
506	  bool has_ref_attr;
507	  TF_RETURN_IF_ERROR(
508	      GetNodeAttr(n->attrs(), kXlaHasReferenceVarsAttr, &has_ref_attr));
509	  xla_compile.operation.node()->AddAttr(kXlaHasReferenceVarsAttr, has_ref_attr);
510	  TF_RETURN_IF_ERROR(
511	      CopyIncomingControlEdges(g, /*from=*/n, /*to=*/xla_compile.key.node()));
512	
513	  std::vector<Output> xla_run_args =
514	      GetXlaRunArgs(root, cluster_info, debugging_opts);
515	
516	  if (requires_compilation) {
517	    // "Strict" compilation:  every _XlaCompile invocation must compile the
518	    // cluster.
519	    ops::_XlaRun xla_run(root.WithOpName("xla_run"), xla_run_args,
520	                         xla_compile.key, n->output_types());
521	
522	    MoveOutgoingEdges(g, /*old_node=*/n,
523	                      /*new_node=*/xla_run.operation.node());
524	    g->RemoveNode(n);
525	  } else {
526	    // "Lazy" compilation: an _XlaCompile invocation may decide not to compile
527	    // the cluster based on profitability heuristics.
528	
529	    // We generate the following graph:
530	    //
531	    //   (use_tf_call, use_xla_run) =
532	    //       Switch(pred=xla_compile.compilation_successful,
533	    //              value=xla_compile.key)
534	    //
535	    //   tf_call_outputs = cluster_N(..., ^use_tf_call)
536	    //   xla_run_outputs = _XlaRun(..., key=use_xla_run)
537	    //   outputs = Merge(tf_call_outputs, xla_run_outputs).
538	    ops::Switch s(root.WithOpName("predicated_compilation_key"),
539	                  xla_compile.key, xla_compile.compilation_successful);
540	    Output predicated_compilation_key = s.output_true;
541	    Output inverse_predicated_compilation_key = s.output_false;
542	
543	    ops::_XlaRun xla_run(root.WithOpName("xla_run"), xla_run_args,
544	                         predicated_compilation_key, n->output_types());
545	
546	    MergeOutgoingControlEdges(root, /*old_node=*/n,
547	                              /*new_node=*/xla_run.operation.node());
548	
549	    MergeOutgoingDataEdges(root, /*old_node=*/n,
550	                           /*new_node=*/xla_run.operation.node(),
551	                           cluster_info.function.name(), debugging_opts);
552	
553	    TF_RETURN_IF_ERROR(root.status());
554	
555	    // We already have a TensorFlow function call into the cluster -- the
556	    // original node we set out to rewrite.  We just wire in the correct control
557	    // deps and we're done.
558	    RemoveAllIncomingControlEdges(g, n);
559	    Operation inverse_predicate_as_control =
560	        DataToControl(root, inverse_predicated_compilation_key);
561	    g->AddControlEdge(inverse_predicate_as_control.node(), n);
562	    n->ClearAttr(kXlaCompiledKernelAttr);
563	
564	    TF_ASSIGN_OR_RETURN(Node* const pco, ReplaceFunctionCallWithPartitionedCall(
565	                                             options, flib_def, n, g,
566	                                             cluster_info.function, root));
567	
568	    TF_RETURN_IF_ERROR(
569	        PredicateInt32Inputs(root, pco, inverse_predicate_as_control));
570	  }
571	
572	  return absl::OkStatus();
573	}
574	}  // namespace
575	
576	absl::Status BuildXlaOpsPass::Run(const GraphOptimizationPassOptions& options) {
577	  Graph* graph = options.graph->get();
578	
579	  // Copy out the nodes we want to rewrite to avoid modifying the graph while we
580	  // iterate on graph->op_nodes().
581	  std::vector<Node*> xla_compiled_kernels;
582	  absl::c_copy_if(graph->op_nodes(), std::back_inserter(xla_compiled_kernels),
583	                  [](const Node* n) {
584	                    if (n->IsSend() || n->IsRecv() || n->IsControlFlow()) {
585	                      return false;
586	                    }
587	
588	                    // Only compile nodes that are marked for compilation by the
589	                    // compilation-marking pass (via 'attr_name').
590	                    return IsXlaCompiledKernel(*n);
591	                  });
592	
593	  bool lazy_compilation_enabled =
594	      enable_lazy_compilation_
595	          ? *enable_lazy_compilation_
596	          : GetBuildXlaOpsPassFlags()->tf_xla_enable_lazy_compilation;
597	
598	  jit::DeviceInfoCache device_info_cache;
599	  const BuildXlaOpsPassFlags& flags = *GetBuildXlaOpsPassFlags();
600	
601	  DebuggingOpts debugging_opts;
602	  debugging_opts.print_outputs = flags.tf_xla_print_cluster_outputs;
603	  debugging_opts.check_input_numerics =
604	      flags.tf_xla_check_cluster_input_numerics;
605	  debugging_opts.check_output_numerics =
606	      flags.tf_xla_check_cluster_output_numerics;
607	
608	  VLOG(1) << "print_outputs = " << debugging_opts.print_outputs;
609	  VLOG(1) << "check_input_numerics = " << debugging_opts.check_input_numerics;
610	  VLOG(1) << "check_output_numerics = " << debugging_opts.check_output_numerics;
611	
612	  for (Node* n : xla_compiled_kernels) {
613	    TF_RETURN_IF_ERROR(ReplaceNodeWithXlaCompileAndXlaRun(
614	        &device_info_cache, options, *options.flib_def,
615	        lazy_compilation_enabled, debugging_opts, graph, n));
616	  }
617	
618	  if (VLOG_IS_ON(1)) {
619	    DumpGraphToFile("build_xla_ops", *graph, options.flib_def);
620	  }
621	
622	  return absl::OkStatus();
623	}
624	}  // namespace tensorflow
