72	namespace {
73	// Returns a string describing how an edge from src to dst would
74	// create a cycle.
75	std::string DescribeCycle(const xla::GraphCycles* cycles, const Graph& graph,
76	                          int src, int dst) {
77	  int32_t max_path_size = graph.num_node_ids() + 1;
78	  std::vector<int32_t> path(max_path_size);
79	  int32_t path_size = cycles->FindPath(dst, src, max_path_size, path.data());
80	  if (path_size == 0) {
81	    return "";
82	  }
83	
84	  auto node_name = [&graph](int node_id) {
85	    if (!FastBoundsCheck(node_id, graph.num_node_ids())) {
86	      return std::string("(null)");
87	    }
88	    auto* node = graph.FindNodeId(node_id);
89	    if (node == nullptr) {
90	      return std::string("(null)");
91	    }
92	    return node->name();
93	  };
94	
95	  std::string description;
96	  absl::StrAppend(&description, "Edge from ", node_name(src), " to ",
97	                  node_name(dst), " would create a cycle.\n");
98	  path.resize(path_size);
99	  for (int32_t node_id : path) {
100	    std::string ascii_art;
101	    if (node_id == dst) {
102	      ascii_art = "+-> ";
103	    } else if (node_id != src) {
104	      ascii_art = "|   ";
105	    } else {
106	      ascii_art = "+-- ";
107	    }
108	    absl::StrAppend(&description, ascii_art, node_name(node_id), "\n");
109	  }
110	  return description;
111	}
