117	bool HasForwardedRefInput(const Node& node) {
118	  if (AlwaysForwardsRefInput(node)) {
119	    for (const Edge* incoming_edge : node.in_edges()) {
120	      if (incoming_edge->IsControlEdge()) {
121	        continue;
122	      }
123	
124	      Node* incoming_node = incoming_edge->src();
125	      if (IsRefType(incoming_node->output_type(incoming_edge->src_output()))) {
126	        VLOG(2) << "Node " << node.def().ShortDebugString() << " has ref input "
127	                << incoming_node->name() << " " << incoming_node->type_string();
128	        return true;
129	      }
130	    }
131	  }
132	  return false;
133	}
