135	absl::StatusOr<bool> CreateCycleDetectionGraph(const Graph* graph,
136	                                               xla::GraphCycles* cycles) {
137	  for (int i = 0; i < graph->num_node_ids(); ++i) {
138	    // We rely on the node IDs in the cycle detection graph being consecutive
139	    // integers starting from 0.
140	    CHECK_EQ(i, cycles->NewNode());
141	  }
142	
143	  // Compute the loop structure of the graph.
144	  std::vector<ControlFlowInfo> control_flow_info;
145	  TF_RETURN_IF_ERROR(BuildControlFlowInfo(graph, &control_flow_info));
146	
147	  // The clustering code must avoid adding cycles to the graph to prevent
148	  // deadlock. However, the graph may contain loops, which would trigger the
149	  // cycle detection code. To handle loops, we alter the structure of the cycle
150	  // detection graph, disconnecting each loop from the enclosing graph.
151	  // Specifically, we:
152	  // * add a new "frame" node for each loop.
153	  // * replace edges to "Enter" nodes, and edges from "Exit" nodes with edges
154	  //   to/from the corresponding frame node. In essence, we collapse the loop
155	  //   into a single node for the purpose of cycle detection in the enclosing
156	  //   graph.
157	  // * the body of the loop should now be disconnected from the rest of the
158	  //   graph; we make it acyclic by breaking loop backedges (edges outgoing from
159	  //   "NextIteration" nodes.
160	
161	  // Map from frame name strings to node IDs in the cycle detection graph.
162	  std::unordered_map<std::string, int> frame_nodes;
163	
164	  // Get the cycle graph node ID for frame 'frame_name', or add one if none
165	  // exists.
166	  auto GetOrAddFrameNodeId = [&frame_nodes,
167	                              cycles](const std::string& frame_name) {
168	    int& frame_id = frame_nodes.emplace(frame_name, -1).first->second;
169	    if (frame_id < 0) {
170	      // The emplace succeeded; we have not allocated a frame node yet.
171	      frame_id = cycles->NewNode();
172	    }
173	    return frame_id;
174	  };
175	
176	  for (Edge const* edge : graph->edges()) {
177	    if (edge->dst()->IsEnter() || edge->src()->IsExit()) {
178	      const char* src_type = "pre-enter";
179	      const char* dst_type = "post-exit";
180	      int src = edge->src()->id();
181	      int dst = edge->dst()->id();
182	
183	      if (edge->dst()->IsEnter()) {
184	        // Lift edges to an "Enter" node to the corresponding frame node.
185	        const std::string& frame_name =
186	            control_flow_info[edge->dst()->id()].frame_name;
187	        dst = GetOrAddFrameNodeId(frame_name);
188	        dst_type = "frame";
189	      }
190	
191	      if (edge->src()->IsExit()) {
192	        // Lift edges from an "Exit" node to the corresponding frame node.
193	        const std::string& frame_name =
194	            control_flow_info[edge->src()->id()].frame_name;
195	        src = GetOrAddFrameNodeId(frame_name);
196	        src_type = "frame";
197	      }
198	
199	      if (!cycles->InsertEdge(src, dst)) {
200	        // TODO(b/127521408): We can probably handle this situation with a more
201	        // sophisticated SCC based algorithm, but for now we bail out.
202	        VLOG(1) << "Cycle detected when adding " << src_type << "->" << dst_type
203	                << " edge: " << DescribeCycle(cycles, *graph, src, dst);
204	        return false;
205	      }
206	      // Drop the original edge.
207	      continue;
208	    }
209	    if (edge->src()->IsNextIteration()) {
210	      // Break loop back-edges.
211	      continue;
212	    }
213	    if (!cycles->InsertEdge(edge->src()->id(), edge->dst()->id())) {
214	      // This should never happen. All cycles in the graph should contain
215	      // a control flow operator.
216	      return absl::InternalError(absl::StrCat(
217	          "Found cycle in graph without control flow operator during XLA "
218	          "compilation: ",
219	          DescribeCycle(cycles, *graph, edge->src()->id(), edge->dst()->id())));
220	    }
221	  }
222	
223	  return true;
224	}
