368	
369	  absl::c_sort(*result, [](const XlaAutoClusteringSummary::OpAndCount& a,
370	                           const XlaAutoClusteringSummary::OpAndCount& b) {
371	    return a.op() < b.op();
372	  });
373	}
374	
375	void ClusterInfoToProtobuf(XlaAutoClusteringSummary::Cluster* result,
376	                           absl::string_view name, const ClusterInfo& info) {
377	  result->set_name(std::string(name));
378	  result->set_size(info.size);
379	  HistogramMapToRepeatedOpAndCount(result->mutable_op_histogram(),
380	                                   info.op_histogram);
381	}
382	}  // namespace
383	
384	XlaAutoClusteringSummary GetXlaAutoClusteringSummary(const Graph& graph) {
385	  absl::flat_hash_map<absl::string_view, ClusterInfo> cluster_name_to_info;
386	  XlaAutoClusteringSummary result;
387	
388	  absl::flat_hash_map<absl::string_view, int> unclustered_op_histogram;
389	
390	  for (Node* n : graph.nodes()) {
391	    std::optional<absl::string_view> cluster_name = GetXlaClusterForNode(*n);
392	    if (cluster_name) {
393	      result.set_clustered_node_count(result.clustered_node_count() + 1);
394	      ClusterInfo* info = &cluster_name_to_info[*cluster_name];
395	      info->size++;
396	      info->op_histogram[n->type_string()]++;
397	    } else {
398	      result.set_unclustered_node_count(result.unclustered_node_count() + 1);
399	      unclustered_op_histogram[n->type_string()]++;
400	    }
401	  }
402	
403	  for (const auto& pair : cluster_name_to_info) {
404	    XlaAutoClusteringSummary::Cluster* new_cluster = result.add_clusters();
405	    ClusterInfoToProtobuf(new_cluster, pair.first, pair.second);
406	  }
407	
408	  absl::c_sort(*result.mutable_clusters(),
409	               [&](const XlaAutoClusteringSummary::Cluster& a,
410	                   const XlaAutoClusteringSummary::Cluster& b) {
411	                 return a.name() < b.name();
412	               });
413	
414	  HistogramMapToRepeatedOpAndCount(result.mutable_unclustered_op_histogram(),
415	                                   unclustered_op_histogram);
416	
417	  return result;
418	}
419	
420	namespace {
421	using CallTargetListTy = absl::InlinedVector<NameAttrList, 2>;
422	
423	CallTargetListTy GetCallTargetListFromNode(
424	    const Node& n, FunctionLibraryRuntime* lib_runtime) {
425	  const FunctionLibraryDefinition& flib_def =
426	      *lib_runtime->GetFunctionLibraryDefinition();
427	  if (flib_def.Find(n.type_string())) {
428	    NameAttrList callee;
429	    callee.set_name(n.type_string());
430	    *callee.mutable_attr() = n.def().attr();
431	    return {callee};
432	  }
433	
434	  CallTargetListTy result;
435	  for (const auto& name_attr_pair : n.attrs()) {
436	    const AttrValue& attr_value = name_attr_pair.second;
437	    if (attr_value.value_case() == AttrValue::kFunc) {
438	      result.push_back(attr_value.func());
439	    } else if (attr_value.value_case() == AttrValue::kList) {
440	      result.insert(result.end(), attr_value.list().func().begin(),
441	                    attr_value.list().func().end());
442	    }
443	  }
444	
445	  return result;
446	}
447	
448	enum class Direction { kForward, kBackward };
449	
450	absl::Status GetNodesRelatedToRefVariablesInDirection(
451	    const Graph& graph, FunctionLibraryRuntime* lib_runtime,
452	    Direction direction, int depth, absl::flat_hash_set<Node*>* result);
453	
454	absl::StatusOr<bool> DoesAnyCalleeHaveRefNodes(
455	    const CallTargetListTy& call_target_list,
456	    FunctionLibraryRuntime* lib_runtime, Direction direction, int depth) {
457	  const int kMaxDepth = 10;
458	
459	  if (depth == kMaxDepth && !call_target_list.empty()) {
460	    // Conservative answer to avoid recursing too much.
461	    return true;
462	  }
463	
464	  absl::flat_hash_set<Node*> callee_ref_nodes;
465	  for (const NameAttrList& call_target : call_target_list) {
466	    const OpRegistrationData* op_reg;
467	    if (OpRegistry::Global()->LookUp(call_target.name(), &op_reg).ok()) {
468	      const OpDef& op = op_reg->op_def;
469	      if (absl::c_any_of(op.output_arg(), [](const OpDef::ArgDef arg) {
470	            return arg.is_ref();
471	          })) {
472	        return true;
473	      }
474	      continue;
475	    }
476	
477	    callee_ref_nodes.clear();
478	    FunctionLibraryRuntime::Handle handle;
479	    if (!lib_runtime
480	             ->Instantiate(call_target.name(), AttrSlice(&call_target.attr()),
481	                           &handle)
482	             .ok()) {
483	      VLOG(2) << "Could not find " << call_target.name()
484	              << " in the function library.";
485	      // Since we don't know the semantic of `n` we don't know if this is an
486	      // error.  We return true to signal a conservative answer.
487	      return true;
488	    }
489	
490	    auto release_handle_on_return =
491	        gtl::MakeCleanup([&] { CHECK_OK(lib_runtime->ReleaseHandle(handle)); });
492	
493	    const FunctionBody* fbody = lib_runtime->GetFunctionBody(handle);
494	    TF_RETURN_IF_ERROR(GetNodesRelatedToRefVariablesInDirection(
495	        *fbody->graph, lib_runtime, direction, depth + 1, &callee_ref_nodes));
496	
497	    // We could possibly use something cheaper than
498	    // GetNodesRelatedToRefVariablesInDirection since we only care about the
499	    // size of `callee_ref_nodes` but for now we don't ceare.
500	    if (!callee_ref_nodes.empty()) {
501	      return true;
502	    }
503	  }
504	
505	  return false;
506	}
507	
508	// Helper for GetNodesRelatedToRefVariables that traverses the graph in one
509	// direction.
510	absl::Status GetNodesRelatedToRefVariablesInDirection(
511	    const Graph& graph, FunctionLibraryRuntime* lib_runtime,
512	    Direction direction, int depth, absl::flat_hash_set<Node*>* result) {
513	  std::vector<Node*> nodes_in_order;
514	  if (direction == Direction::kForward) {
515	    GetReversePostOrder(graph, &nodes_in_order,
516	                        /*stable_comparator=*/NodeComparatorName());
517	  } else {
518	    GetPostOrder(graph, &nodes_in_order,
519	                 /*stable_comparator=*/NodeComparatorName());
520	  }
521	
522	  size_t old_result_size;
523	  int iterations = 0;
524	
525	  const int kMaxIterations = 10 * 1000;
526	
527	  std::vector<bool> callee_has_ref_nodes_cache;
528	  callee_has_ref_nodes_cache.resize(graph.num_node_ids());
529	
530	  auto does_callee_have_ref_nodes = [&](Node* n) -> absl::StatusOr<bool> {
531	    if (iterations == 1) {
532	      TF_ASSIGN_OR_RETURN(
533	          bool callee_has_ref_nodes,
534	          DoesAnyCalleeHaveRefNodes(GetCallTargetListFromNode(*n, lib_runtime),
535	                                    lib_runtime, direction, depth));
536	      callee_has_ref_nodes_cache[n->id()] = callee_has_ref_nodes;
537	      return callee_has_ref_nodes;
538	    } else {
539	      return {callee_has_ref_nodes_cache[n->id()]};
540	    }
541	  };
542	
543	  do {
544	    TF_RET_CHECK(iterations++ < kMaxIterations) << "infinite loop?";
545	
546	    old_result_size = result->size();
547	    for (Node* n : nodes_in_order) {
548	      if (n->IsSource() || n->IsSink()) {
549	        continue;
550	      }
551	
552	      bool inserted_n = false;
553	      const EdgeSet& edges =
554	          direction == Direction::kForward ? n->in_edges() : n->out_edges();
555	      for (const Edge* e : edges) {
556	        if (result->contains(direction == Direction::kForward ? e->src()
557	                                                              : e->dst())) {
558	          result->insert(n);
559	          inserted_n = true;
560	          break;
561	        }
562	      }
563	
564	      if (inserted_n) {
565	        continue;
566	      }
567	
568	      if (direction == Direction::kForward &&
569	          absl::c_any_of(n->output_types(), IsRefType)) {
570	        result->insert(n);
571	        continue;
572	      }
573	
574	      TF_ASSIGN_OR_RETURN(bool callee_has_ref_nodes,
575	                          does_callee_have_ref_nodes(n));
576	      if (callee_has_ref_nodes) {
577	        result->insert(n);
578	        continue;
579	      }
580	    }
581	
582	    // Loop until convergence.
583	  } while (result->size() != old_result_size);
584	
585	  VLOG(2) << "# iterations = " << iterations;
586	
587	  return absl::OkStatus();
588	}
589	
590	// Sorts control inputs of a graphdef so that they are deterministically
591	// ordered.
592	void SortControlInputs(GraphDef* gdef) {
593	  int64_t num_nodes = gdef->node_size();
594	  for (int64_t i = 0; i < num_nodes; ++i) {
595	    NodeDef* node = gdef->mutable_node(i);
596	    // Stable sort control inputs and leave the order of data inputs unchanged.
597	    std::stable_sort(node->mutable_input()->begin(),
598	                     node->mutable_input()->end(),
599	                     [](const std::string& a, const std::string& b) {
600	                       bool a_is_control = absl::StartsWith(a, "^");
601	                       bool b_is_control = absl::StartsWith(b, "^");
602	                       return (!a_is_control && b_is_control) ||
603	                              (a_is_control && b_is_control && a < b);
604	                     });
605	  }
606	}
607	}  // namespace
608	
609	absl::StatusOr<absl::flat_hash_set<Node*>> GetNodesRelatedToRefVariables(
610	    const Graph& graph, FunctionLibraryRuntime* lib_runtime) {
611	  absl::flat_hash_set<Node*> result;
612	  TF_RETURN_IF_ERROR(GetNodesRelatedToRefVariablesInDirection(
613	      graph, lib_runtime, Direction::kForward, 0, &result));
614	  TF_RETURN_IF_ERROR(GetNodesRelatedToRefVariablesInDirection(
615	      graph, lib_runtime, Direction::kBackward, 0, &result));
616	
617	  VLOG(1) << "GetNodesRelatedToRefVariables() found " << result.size()
618	          << " nodes";
619	  return result;
620	}
621	
622	absl::StatusOr<std::string> SerializeGraphDeterministic(const Graph& graph) {
623	  GraphDef def;
624	  graph.ToGraphDef(&def);
625	
626	  // Before serialization, sort each node's control inputs to achieve
627	  // determinism. Sorting control inputs could help (but not necessarily) create
628	  // a deterministic serialization and fingerprint. Other sources of
629	  // nondeterminism include unstable node ordering.
630	  SortControlInputs(&def);
631	
632	  std::string s;
633	  if (!SerializeToStringDeterministic(def, &s)) {
634	    return absl::InternalError("Failed to serialize graphdef.");
635	  }
636	  return s;
637	}
638	
639	absl::StatusOr<uint64_t> FingerprintGraph(const Graph& graph) {
640	  TF_ASSIGN_OR_RETURN(std::string serialized,
641	                      SerializeGraphDeterministic(graph));
642	  return Hash64(serialized.data(), serialized.size());
643	}
644	
645	// Register a callback for querying XlaGlobalJitLevel.
646	REGISTER_XLA_CONFIG_GETTER(GetXlaGlobalJitLevel);
647	
648	}  // namespace tensorflow
