695	absl::StatusOr<bool> MarkForCompilationPassImpl::ForEachEdgeInPostOrder(
696	    FnTy fn) {
697	  bool changed = false;
698	  for (int32_t node : cycles_graph_.AllNodesInPostOrder()) {
699	    Cluster* cluster_from = GetClusterForCyclesGraphNode(node);
700	    if (!cluster_from) {
701	      continue;
702	    }
703	
704	    // Make a copy of the set of successors because we may modify the graph in
705	    // TryToContractEdge.
706	    std::vector<int32_t> successors_copy =
707	        cycles_graph_.SuccessorsCopy(cluster_from->cycles_graph_node_id());
708	
709	    for (int to : successors_copy) {
710	      iteration_count_++;
711	
712	      Cluster* cluster_to = GetClusterForCyclesGraphNode(to);
713	      if (!cluster_to) {
714	        continue;
715	      }
716	
717	      TF_ASSIGN_OR_RETURN(bool contracted_edge, fn(cluster_from, cluster_to));
718	      changed |= contracted_edge;
719	    }
720	  }
721	
722	  return changed;
723	}
